   /// <summary>
   /// PaffH 10.11.25
   /// last modified: PaffH 25.11.25
   /// </summary>
   /// <param name = "_sectionType">NDXBVEmailRequestSectionType</param>
protected void new(NDXBVEmailRequestSectionType _sectionType)
   {
       super(_sectionType);

       this.addFields2Section(0, 
           fieldNum(NDXBVEMailRequestLineAIDecisionBasis, AIDBDocument),
           0);
       this.addFields2Section(fieldNum(NDXBVEMailRequestLine, IdentifierInquirer), 
           fieldNum(NDXBVEMailRequestLineAIDecisionBasis,IdentifierInquirerAIDB),
           fieldNum(NDXBVEMailRequestLineAIInfo, IdentifierInquirerAII));
       this.addFields2Section(fieldNum(NDXBVEMailRequestLine, RequestedQuantityQty), 
           fieldNum(NDXBVEMailRequestLineAIDecisionBasis, RequestedQuantityQtyAIDB),
           fieldNum(NDXBVEMailRequestLineAIInfo, RequestedQuantityQtyAII));
       this.addFields2Section(fieldNum(NDXBVEMailRequestLine, RequestedQuantityUnitId), 
           fieldNum(NDXBVEMailRequestLineAIDecisionBasis, RequestedQuantityUnitIdAIDB),
           fieldNum(NDXBVEMailRequestLineAIInfo, RequestedQuantityUnitIdAII));
       this.addFields2Section(fieldNum(NDXBVEMailRequestLine, TenderProjectLineId), 
           fieldNum(NDXBVEMailRequestLineAIDecisionBasis, TenderProjectLineIdAIDB),
           fieldNum(NDXBVEMailRequestLineAIInfo, TenderProjectLineIdAII));
       this.addFields2Section(fieldNum(NDXBVEMailRequestLine, ItemIdentifier), 
           fieldNum(NDXBVEMailRequestLineAIDecisionBasis, ItemIdentifierAIDB),
           fieldNum(NDXBVEMailRequestLineAIInfo, ItemIdentifierAII));
       this.addFields2Section(fieldNum(NDXBVEMailRequestLine, ItemEANCode), 
           fieldNum(NDXBVEMailRequestLineAIDecisionBasis, ItemEANCodeAIDB),
           fieldNum(NDXBVEMailRequestLineAIInfo, ItemEANCodeAII));
       this.addFields2Section(fieldNum(NDXBVEMailRequestLine, ItemName), 
           fieldNum(NDXBVEMailRequestLineAIDecisionBasis, ItemNameAIDB),
           fieldNum(NDXBVEMailRequestLineAIInfo, ItemNameAII));
   }

/// <summary>
/// PaffH 10.11.25
/// last modified: PaffH 25.11.25
/// </summary>
/// <param name = "_fieldIdAiField">FieldId</param>
/// <param name = "_fieldIdaiFieldDecisionBase">FieldId</param>
/// <param name = "_fieldIdaiFieldInfo">FieldId</param>
private void addFields2Section(FieldId _fieldIdAiField, FieldId _fieldIdaiFieldDecisionBase, FieldId _fieldIdAiFieldInfo)
{
    NDXBVEMailRequestLine nDXBVEMailRequestLine;
    NDXBVEMailRequestLineAIDecisionBasis nDXBVEMailRequestLineAIDecisionBasis;
    NDXBVEMailRequestLineAIInfo nDXBVEMailRequestLineAIInfo;

    NDXBVEmailRequestAIDBFieldContract aiField = NDXBVEmailRequestAIDBFieldContract::constructFromCommon(nDXBVEMailRequestLine, _fieldIdAiField);
    NDXBVEmailRequestAIDBFieldDecisionBaseContract aiFieldDecisionBase = NDXBVEmailRequestAIDBFieldDecisionBaseContract::constructFromCommon(nDXBVEMailRequestLineAIDecisionBasis, _fieldIdaiFieldDecisionBase);
    NDXBVEmailRequestAIDBFieldInfoContract aiFieldInfo = NDXBVEmailRequestAIDBFieldInfoContract::constructFromCommon(nDXBVEMailRequestLineAIInfo, _fieldIdAiFieldInfo);
    sectionGroups.addEnd(NDXBVEmailRequestAIDBSectionGroupContract::construct(aiField, aiFieldDecisionBase, aiFieldInfo));
}

/// <summary>
/// PaffH 10.11.25
/// </summary>
/// <returns>NDXBVEmailRequestAIDBSectionLineItemContract</returns>
public static NDXBVEmailRequestAIDBSectionLineItemContract construct()
{
    NDXBVEmailRequestAIDBSectionLineItemContract section = new NDXBVEmailRequestAIDBSectionLineItemContract(NDXBVEmailRequestSectionType::ItemLine);
    return section;
}
